DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.manage_security_bulletin(uuid,integer,text,jsonb,text,boolean)'::regprocedure) INTO definition; definition := replace(definition, 'bulletin_id uuid, expected_revision integer, operation text, public_content jsonb, decision_note text, privacy_reviewed boolean', 'bulletin_id uuid DEFAULT NULL, expected_revision integer DEFAULT NULL, operation text DEFAULT NULL, public_content jsonb DEFAULT NULL, decision_note text DEFAULT NULL, privacy_reviewed boolean DEFAULT false'); EXECUTE definition; END $$;